create or replace function public.audit_review_visibility_change() returns trigger language plpgsql security definer set search_path='' as $$ begin if old.is_visible is distinct from new.is_visible and coalesce(auth.jwt()->>'role','')<>'service_role' then perform public.write_admin_audit(case when new.is_visible then 'review.restored' else 'review.hidden' end,'review',new.id,jsonb_build_object('is_visible',old.is_visible),jsonb_build_object('is_visible',new.is_visible),'Decision de moderation'); end if; return new; end; $$; revoke all on function public.audit_review_visibility_change() from public,anon,authenticated; drop trigger if exists review_visibility_audit on public.reviews; create trigger review_visibility_audit after update of is_visible on public.reviews for each row execute function public.audit_review_visibility_change();
